    function ValidateCerIssued(source, args) {
        var textInput = document.getElementById('<%= dtmCerIssued.ClientID %>_dateInput_text');
        if (textInput == null) {
            args.IsValid = false;
            return;
        }

        args.IsValid = textInput.value.replace(/^\s+|\s+$/g, '') != '';

        if (!args.IsValid) {
            textInput.classList.add('is-invalid');
        } else {
            textInput.classList.remove('is-invalid');
        }
    }
